class Solution:
    def countSubstrings(self, s: str) -> int:
        # counts[m][r] = number of substrings ending at the previous position
        # whose value is congruent to r modulo m.
        counts = [None] + [[0] * m for m in range(1, 10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for m in range(1, 10):
                nxt = [0] * m

                for r, cnt in enumerate(counts[m]):
                    if cnt:
                        nxt[(r * 10 + digit) % m] += cnt

                # Substring consisting only of the current digit.
                nxt[digit % m] += 1
                counts[m] = nxt

            if digit != 0:
                ans += counts[digit][0]

        return ans
